const maxWorkflowStatePosition = `-- name: MaxWorkflowStatePosition :one
SELECT COALESCE(max(position), 0)::double precision FROM workflow_states WHERE team_id = $1
`

func (q *Queries) MaxWorkflowStatePosition(ctx context.Context, teamID uuid.UUID) (float64, error) {
	row := q.db.QueryRow(ctx, maxWorkflowStatePosition, teamID)
	var column_1 float64
	err := row.Scan(&column_1)
	return column_1, err
}

const raiseNextIssueNumber = `-- name: RaiseNextIssueNumber :exec
UPDATE teams
SET next_issue_number = GREATEST(next_issue_number, (SELECT COALESCE(max(i.number), 0) + 1 FROM issues i WHERE i.team_id = teams.id))
WHERE teams.id = $1
`

// After an import, new issues are numbered after the highest one there is.
func (q *Queries) RaiseNextIssueNumber(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, raiseNextIssueNumber, id)
	return err
}

const releaseImport = `-- name: ReleaseImport :exec
UPDATE imports SET heartbeat_at = 'epoch', stage = 'Resuming' WHERE id = $1 AND status = 'running'
`

// A server that is shutting down hands its import to whichever starts next.
func (q *Queries) ReleaseImport(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, releaseImport, id)
	return err
}

