const upsertImportConnection = `-- name: UpsertImportConnection :one
INSERT INTO import_connections (id, workspace_id, user_id, provider, label, secret)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (workspace_id, user_id, provider) DO UPDATE
SET label = EXCLUDED.label, secret = EXCLUDED.secret, updated_at = now()
RETURNING id, workspace_id, user_id, provider, label, secret, created_at, updated_at
`

type UpsertImportConnectionParams struct {
	ID          uuid.UUID
	WorkspaceID uuid.UUID
	UserID      uuid.UUID
	Provider    string
	Label       string
	Secret      []byte
}

func (q *Queries) UpsertImportConnection(ctx context.Context, arg UpsertImportConnectionParams) (ImportConnection, error) {
	row := q.db.QueryRow(ctx, upsertImportConnection,
		arg.ID,
		arg.WorkspaceID,
		arg.UserID,
		arg.Provider,
		arg.Label,
		arg.Secret,
	)
	var i ImportConnection
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.UserID,
		&i.Provider,
		&i.Label,
		&i.Secret,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
